from pathlib import Path
from html import escape
import json
import shutil

ROOT = Path(__file__).parent
OUT = ROOT / 'dist'
BASE = 'https://fireworks-painting.vercel.app'
OUT.mkdir(exist_ok=True)
shutil.copytree(ROOT / 'assets', OUT / 'assets', dirs_exist_ok=True)
shutil.copy(ROOT / 'styles.css', OUT / 'styles.css')
shutil.copy(ROOT / 'script.js', OUT / 'script.js')
shutil.copy(ROOT / 'vercel.json', OUT / 'vercel.json')

nav = [('Home','/'),('Services','/services/'),('Projects','/projects/'),('Service Areas','/service-areas/'),('Estimate','/estimate/')]
def button(label='Request an estimate', href='/estimate/', secondary=False):
    return f'<a class="button {"button-outline" if secondary else ""}" href="{href}">{label}<span aria-hidden="true">↗</span></a>'

def card(title, body, href=None, eyebrow=None):
    inner = f'<p class="eyebrow">{eyebrow}</p>' if eyebrow else ''
    inner += f'<h3>{title}</h3><p>{body}</p>'
    inner += f'<span class="text-link">Explore service <span aria-hidden="true">↗</span></span>' if href else ''
    return f'<{"a href="+chr(34)+href+chr(34) if href else "div"} class="card">{inner}</{"a" if href else "div"}>'

def page(slug, title, description, body, active, noindex=False):
    canonical = BASE + (f'/{slug}/' if slug else '/')
    links = ''.join(f'<a href="{href}"' + (' aria-current="page"' if label == active else '') + f'>{label}</a>' for label,href in nav)
    schema = {'@context':'https://schema.org','@type':'HomeAndConstructionBusiness','name':'Field & Finish Painting — fictional demo','url':BASE,'description':'Fictional FireWorks painting contractor website template. Sample business details only.','areaServed':{'@type':'Place','name':'Client service area to be confirmed'}}
    html = f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(description)}"><meta name="robots" content="{'noindex,nofollow' if noindex else 'index,follow'}"><link rel="canonical" href="{canonical}"><meta property="og:type" content="website"><meta property="og:title" content="{escape(title)}"><meta property="og:description" content="{escape(description)}"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}/assets/painting-preview.webp"><meta name="twitter:card" content="summary_large_image"><link rel="icon" href="/assets/favicon.svg" type="image/svg+xml"><link rel="preload" as="image" href="/assets/painting-hero.webp"><link rel="stylesheet" href="/styles.css"><script type="application/ld+json">{json.dumps(schema)}</script><script src="/script.js" defer></script></head><body><a class="skip-link" href="#content">Skip to content</a><div class="demo-ribbon">FIREWORKS WEBSITE TEMPLATE · FICTIONAL COMPANY · REQUESTS ARE NOT SENT</div><header class="site-header"><a class="brand" href="/" aria-label="Field and Finish home"><span class="brand-icon">F<span class="brand-stroke"></span></span><span>FIELD <em>&</em> FINISH<small>PAINTING CO. — DEMO</small></span></a><button class="menu-toggle" type="button" aria-label="Open navigation" aria-expanded="false" aria-controls="site-nav"><span></span><span></span><span></span></button><nav class="site-nav" id="site-nav" aria-label="Main navigation">{links}</nav><a class="header-cta" href="/estimate/">Get an estimate <span aria-hidden="true">↗</span></a></header><main id="content">{body}</main><footer class="footer"><div><a class="brand" href="/"><span class="brand-icon">F<span class="brand-stroke"></span></span><span>FIELD <em>&</em> FINISH<small>PAINTING CO. — DEMO</small></span></a><p>A reusable painting contractor website by FireWorks. All business details and project examples are illustrative.</p></div><div><strong>Explore</strong><a href="/services/">Services</a><a href="/projects/">Project concepts</a><a href="/service-areas/">Service areas</a><a href="/estimate/">Estimate request</a></div><div><strong>Launch checklist</strong><p>Client name, service area, contact details, credentials, photos, hours and inquiry delivery must be confirmed before a live business launch.</p></div><div class="copyright">© FireWorks demo. This form does not send or store requests.</div></footer></body></html>'''
    folder = OUT / slug if slug else OUT
    folder.mkdir(exist_ok=True)
    (folder/'index.html').write_text(html,encoding='utf-8')

home = f'''<section class="hero"><div class="hero-image" role="img" aria-label="Professional painter applying a finish to a residential wall"></div><div class="hero-shade"></div><div class="hero-content"><p class="eyebrow light">A BETTER FINISH BEGINS WITH A BETTER PLAN</p><h1>Color that feels <i>like home.</i></h1><p>Thoughtful prep, clean lines and a finish built around the space you live or work in.</p><div class="actions">{button()}{button('Explore services','/services/',True)}</div><p class="hero-note">Fictional painting company demo · Client availability and coverage to be confirmed</p></div><span class="hero-index">01 / THE FINISH</span></section><section class="quick-strip"><span>INTERIORS</span><span>EXTERIORS</span><span>COMMERCIAL SPACES</span><span>DETAILED PREPARATION</span></section><section class="section intro"><div><p class="eyebrow">THE DIFFERENCE IS IN THE DETAILS</p><h2>A fresh coat is only the beginning.</h2></div><div><p class="lead">Good painting work starts long before the first brushstroke. This template puts the process, scope and estimate path where customers can actually find them.</p>{button('See how projects work','/services/',True)}</div></section><section class="section warm"><div class="section-head"><div><p class="eyebrow">WHAT WE CAN PAINT</p><h2>For every kind of space.</h2></div><p>Service categories are examples. Replace them with the work the client actually provides.</p></div><div class="card-grid">{card('Interior painting','Walls, ceilings and trim with a thoughtful plan for occupied spaces.','/services/#interior','01 / RESIDENTIAL')}{card('Exterior painting','Surface preparation and finish selection suited to the property.','/services/#exterior','02 / RESIDENTIAL')}{card('Commercial painting','Flexible scope planning for offices, storefronts and managed properties.','/services/#commercial','03 / COMMERCIAL')}</div></section><section class="section split"><div class="editorial-photo"><img src="/assets/painting-hero.webp" alt="Painter rolling a protected living-room wall" loading="lazy"></div><div><p class="eyebrow">A CLEARER WAY TO START</p><h2>Tell us about your space. We’ll plan the next step.</h2><p>Choose the surfaces, property type and timeframe that fit your project. The estimate form is a safe demo preview and does not send information.</p><ol class="steps"><li><b>01</b><span>Describe the project</span></li><li><b>02</b><span>Review a proposed scope</span></li><li><b>03</b><span>Arrange an on-site conversation</span></li></ol>{button()}</div></section><section class="section dark-cta"><p class="eyebrow light">LET'S MAKE THE ROOM FEEL RIGHT</p><h2>Ready for a fresh perspective?</h2><p>Start with a few details about your painting project.</p>{button()}</section>'''
page('', 'Field & Finish Painting | Contractor Website Demo', 'Explore the Field & Finish painting contractor demo with interior, exterior and commercial services, project concepts and a safe estimate preview.', home, 'Home')

services = f'''<section class="page-hero"><p class="eyebrow">THE SERVICES / DEMO</p><h1>Good work starts <i>under the surface.</i></h1><p>Residential and commercial painting pathways built to explain the work before the estimate.</p>{button()}</section><section class="section service-list"><article id="interior"><p class="eyebrow">01 / INTERIOR</p><h2>Rooms worth coming home to.</h2><p>Walls, ceilings, trim, doors and accent areas. This section can describe protection of furnishings, repair preparation, coating selection and a clean closeout.</p><ul><li>Living spaces and kitchens</li><li>Trim, doors and ceilings</li><li>Color planning and preparation</li></ul>{button('Describe an interior project')}</article><article id="exterior"><p class="eyebrow">02 / EXTERIOR</p><h2>First impressions that hold up.</h2><p>Exterior services should be tailored to the materials and conditions a real client handles. Weather, access, surface repairs and coating choice all inform the scope.</p><ul><li>Siding and trim</li><li>Entryways and porches</li><li>Surface cleaning and preparation</li></ul>{button('Describe an exterior project')}</article><article id="commercial"><p class="eyebrow">03 / COMMERCIAL</p><h2>Plans that work around your business.</h2><p>A clear commercial intake route for offices, retail interiors and managed properties, with scheduling and site constraints confirmed by the actual provider.</p><ul><li>Offices and retail spaces</li><li>Multi-unit common areas</li><li>Scope and schedule review</li></ul>{button('Describe a commercial project')}</article></section><section class="section process"><div class="section-head"><div><p class="eyebrow">THE PROCESS</p><h2>Preparation makes the finish.</h2></div><p>Replace these example stages with the client’s actual process and warranty terms.</p></div><div class="card-grid">{card('Walk-through','Review surfaces, access and goals before proposing a scope.',eyebrow='01')}{card('Protect & prepare','Plan the masking, patching and surface preparation appropriate to the job.',eyebrow='02')}{card('Paint & review','Apply specified finishes, then review the completed work and cleanup.',eyebrow='03')}</div></section>'''
page('services', 'Painting Services | Field & Finish Demo', 'View sample interior, exterior and commercial painting service pathways with a clear preparation process and estimate request.', services, 'Services')

projects = f'''<section class="page-hero"><p class="eyebrow">THE POSSIBILITIES / DEMO</p><h1>Imagine the <i>before and after.</i></h1><p>Illustrative project concepts to show how real client work can be presented later. These are not completed customer projects.</p>{button()}</section><section class="section"><div class="project-grid"><article class="project-feature"><img src="/assets/painting-hero.webp" alt="Illustrative painter at work in a protected room"><div><p class="eyebrow">ILLUSTRATIVE CONCEPT · INTERIOR</p><h2>A room with room to breathe.</h2><p>Sample content: wall and trim finish planning for a lived-in space. Replace with client-owned project imagery and real scope.</p></div></article><article class="project-concept"><div class="swatch swatch-a"></div><p class="eyebrow">ILLUSTRATIVE PALETTE · EXTERIOR</p><h3>A welcoming exterior.</h3><p>Conceptual color study, not a customer project.</p></article><article class="project-concept"><div class="swatch swatch-b"></div><p class="eyebrow">ILLUSTRATIVE PALETTE · COMMERCIAL</p><h3>Space for what comes next.</h3><p>Conceptual color study, not a customer project.</p></article></div></section><section class="section dark-cta"><p class="eyebrow light">YOUR PROJECT IS NEXT</p><h2>Have a space in mind?</h2><p>Tell us about the surfaces and approximate scope to preview the intake.</p>{button()}</section>'''
page('projects', 'Painting Project Concepts | Field & Finish Demo', 'See clearly labeled illustrative painting project concepts and explore an estimate request preview.', projects, 'Projects')

areas = f'''<section class="page-hero"><p class="eyebrow">WHERE WE WORK / DEMO</p><h1>Local service starts <i>with clarity.</i></h1><p>Coverage, travel fees and scheduling must be confirmed with each actual painting client. This template demonstrates useful service-area information without invented city claims.</p>{button('Check your project area')}</section><section class="section split areas-split"><div><p class="eyebrow">SERVICE AREA FRAMEWORK</p><h2>Make the coverage map real.</h2><p>At launch, list the business’s true base location, practical service radius, neighborhoods served and any travel boundaries. Build unique local pages only when the business has useful, distinct information for those places.</p><p>For this demo, customers can enter their city or ZIP in the estimate form. No request is sent.</p>{button('Preview area request')}</div><div class="area-panel"><span>CLIENT INPUT REQUIRED</span><h3>Coverage checklist</h3><ul><li>Verified business address or service-area business setting</li><li>Confirmed cities and ZIP codes</li><li>Residential and commercial travel range</li><li>Accurate hours and contact details</li><li>Any travel or minimum-project policies</li></ul></div></section>'''
page('service-areas', 'Painting Service Areas | Field & Finish Demo', 'A sample painting contractor service-area page designed for accurate local coverage and client customization.', areas, 'Service Areas')

form = '''<form id="estimate-form" class="estimate-form"><p class="form-notice"><strong>Demo only:</strong> This form validates in your browser. It does not send, save, book or share an inquiry.</p><div class="form-grid"><label>Full name <span>*</span><input name="name" autocomplete="name" required maxlength="80"></label><label>Email <span>*</span><input name="email" type="email" autocomplete="email" required maxlength="120"></label><label>Phone <span>*</span><input name="phone" type="tel" autocomplete="tel" required maxlength="30"></label><label>City or ZIP <span>*</span><input name="area" autocomplete="address-level2" required maxlength="80"></label><label>Property type <span>*</span><select name="property" required><option value="">Choose one</option><option>House</option><option>Apartment / condo</option><option>Office / retail</option><option>Managed property</option><option>Other</option></select></label><label>Project type <span>*</span><select name="project" required><option value="">Choose one</option><option>Interior painting</option><option>Exterior painting</option><option>Commercial painting</option><option>Not sure yet</option></select></label><label>Surfaces involved <span>*</span><select name="surfaces" required><option value="">Choose one</option><option>Walls</option><option>Ceilings / trim</option><option>Exterior siding / trim</option><option>Multiple surfaces</option><option>Other / not sure</option></select></label><label>Approximate scope <span>*</span><select name="scope" required><option value="">Choose one</option><option>One room / small area</option><option>Several rooms / medium area</option><option>Whole property / large area</option><option>Not sure</option></select></label><label>Desired timeframe <span>*</span><select name="timeframe" required><option value="">Choose one</option><option>Within 1 month</option><option>1–3 months</option><option>3+ months</option><option>Flexible / planning</option></select></label><label>Preferred contact <select name="contact"><option>Email</option><option>Phone</option></select></label><label class="wide">Project notes (optional)<textarea name="notes" rows="5" maxlength="1000" placeholder="Tell us about the space, prep concerns or access needs. Do not include sensitive information."></textarea></label></div><button type="submit" class="button">Preview request <span aria-hidden="true">↗</span></button><p id="form-result" role="status" aria-live="polite"></p></form>'''
estimate = f'''<section class="page-hero"><p class="eyebrow">LET'S TALK ABOUT THE PROJECT</p><h1>Every finish begins <i>with a conversation.</i></h1><p>Share the basics so a painter can understand the space and next steps. This is a safe demo form; no inquiry is transmitted.</p></section><section class="section estimate-layout"><div><p class="eyebrow">ESTIMATE PREVIEW</p><h2>Tell us what you’re planning.</h2><p>The production version can route validated requests to the client’s chosen email, CRM or scheduling service after credentials, consent text and delivery tests are approved.</p><div class="area-panel"><h3>Helpful details</h3><p>Approximate surface area, property type, timing, access and the area of the property help a painter prepare for a useful conversation.</p></div></div>{form}</section>'''
page('estimate','Request a Painting Estimate | Field & Finish Demo','Preview a detailed painting estimate form covering property type, surfaces, scope, timing, area and contact. Demo inquiries are not sent or stored.',estimate,'Estimate')
(OUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n')
(OUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE}{"/"+s+"/" if s else "/"}</loc></url>' for s in ['','services','projects','service-areas','estimate'])+'</urlset>')
print('Built',len(list(OUT.rglob('index.html'))),'pages')
